      ,Left(
            iif(pro.PRODESPDV = '', ltrim(pro.PRODES), ltrim(pro.PRODESPDV))
           ,40
       ) collate sql_latin1_general_cp1251_ci_as as PRODES
--into #produtos
from TBS010 pro with (nolock)

inner join dbo.vw_PrecoLojaGeral pre
       on pre.codigo = pro.PROCOD

