exec sp_help 'TBS001'

-- DDD do brasil

drop table dbo.DDD_brasil

-- Criar a tabela

CREATE TABLE dbo.DDD_brasil (
    id INT IDENTITY(1,1) PRIMARY KEY,
    uf VARCHAR(10),
    cidade VARCHAR(200),
    ddd VARCHAR(10)
);

-- Criar uma tabela temporária para importar o texto

drop table #tmp_ddd

CREATE TABLE #tmp_ddd (
    linha VARCHAR(500)
);

-- Importar o arquivo

BULK INSERT #tmp_ddd
FROM 'C:\integros\temp\uf.txt'
WITH (
    ROWTERMINATOR = '\n' --,
    --FIELDTERMINATOR = '\t'
);

-- Extrair os campos do texto

-- delete DDD_brasil

INSERT INTO dbo.DDD_brasil (uf, cidade, ddd)
SELECT
    SUBSTRING(
        linha,
        CHARINDEX('''uf'' => ''',linha) + 9,
        CHARINDEX('''', linha, CHARINDEX('''uf'' => ''',linha) + 9)
        - (CHARINDEX('''uf'' => ''',linha) + 9)
    ) AS uf,

    SUBSTRING(
        linha,
        CHARINDEX('''cidade'' => ''',linha) + 13,
        CHARINDEX('''', linha, CHARINDEX('''cidade'' => ''',linha) + 13)
        - (CHARINDEX('''cidade'' => ''',linha) + 13)
    ) AS cidade,

    SUBSTRING(
        linha,
        CHARINDEX('''ddd'' => ''',linha) + 10,
        CHARINDEX('''', linha, CHARINDEX('''ddd'' => ''',linha) + 10)
        - (CHARINDEX('''ddd'' => ''',linha) + 10)
    ) AS ddd

FROM #tmp_ddd
WHERE linha LIKE '%''uf'' =>%';

-- Corrigir cidades com escape

--UPDATE DDD_brasil
--SET cidade = REPLACE(cidade,'\''','''');

SELECT *
FROM DDD_brasil
ORDER BY uf,cidade;

CREATE INDEX IX_DDD_cidade
ON DDD_brasil (cidade);

-- novos atributos

ALTER TABLE dbo.DDD_brasil
ADD cod_ibge_uf SMALLINT,
    cod_ibge_cidade INT;

-- Preencher o código IBGE da UF

UPDATE DDD_brasil SET cod_ibge_uf = 
CASE uf
WHEN 'RO' THEN 11
WHEN 'AC' THEN 12
WHEN 'AM' THEN 13
WHEN 'RR' THEN 14
WHEN 'PA' THEN 15
WHEN 'AP' THEN 16
WHEN 'TO' THEN 17
WHEN 'MA' THEN 21
WHEN 'PI' THEN 22
WHEN 'CE' THEN 23
WHEN 'RN' THEN 24
WHEN 'PB' THEN 25
WHEN 'PE' THEN 26
WHEN 'AL' THEN 27
WHEN 'SE' THEN 28
WHEN 'BA' THEN 29
WHEN 'MG' THEN 31
WHEN 'ES' THEN 32
WHEN 'RJ' THEN 33
WHEN 'SP' THEN 35
WHEN 'PR' THEN 41
WHEN 'SC' THEN 42
WHEN 'RS' THEN 43
WHEN 'MS' THEN 50
WHEN 'MT' THEN 51
WHEN 'GO' THEN 52
WHEN 'DF' THEN 53
END;

select *
  from TBS003 m with (nolock)

exec sp_help 'TBS003'

-- Atualizar o código IBGE da cidade

UPDATE d
SET d.cod_ibge_cidade = m.MUNCOD
FROM DDD_brasil d
JOIN TBS003 m
   ON m.UFESIG = d.uf
  AND RTRIM(m.MUNNOM) = RTRIM(d.cidade);

-- Conferir quantos foram atualizados

SELECT COUNT(*) AS atualizados
FROM DDD_brasil
WHERE cod_ibge_cidade IS NOT NULL;

SELECT COUNT(*) AS atualizados
FROM DDD_brasil
WHERE cod_ibge_cidade IS NULL;

-- Ver cidades que não encontraram correspondência

SELECT d.uf, d.cidade
FROM DDD_brasil d
LEFT JOIN TBS003 m
   ON m.UFESIG = d.uf
  AND RTRIM(m.MUNNOM) = RTRIM(d.cidade)
WHERE m.MUNCOD IS NULL;

