         --on bargz.cdprod = cast(rtrim(pro.PROCOD) as money)
         --on bargz.codbarra = bar.codigo collate database_default
         --on Ltrim(rtrim(cast(bargz.codbarra as varchar(20)))) = rtrim(Ltrim(bar.barras)) collate database_default
         --on Ltrim(rtrim(cast(bargz.codbarra as varchar(20)))) = cast(cast(bar.barras as bigint) as varchar(20)) collate database_default
         on cast(Ltrim(rtrim(bargz.codbarra)) as bigint) = cast(Ltrim(rtrim(bar.barras)) as bigint)
