select *
  from dbo.vw_TabelaCodigosBarrasGZ as bar
 where bar.codigo = '18440002'

select *
  from dbo.vw_PrecoLojaGeral pre
 where pre.codigo = '18440002'

update bargz
   set bargz.termvenda = src.preco
  from openquery(
       MYSQLGZBBPDV3,
       'select id, cdprod,
               codbarra,
               termvenda
          from barrarel'
  ) as bargz

 inner join (
        select pro.PROCOD as cdprod,
               bar.barras,
               bar.preco
          from TBS010 pro with (nolock)
          join dbo.vw_TabelaCodigosBarrasGZ bar
            on bar.codigo = pro.PROCOD
    ) src

         on try_convert(bigint, ltrim(rtrim(bargz.cdprod))) =
            try_convert(bigint, ltrim(rtrim(src.cdprod)))

        and try_convert(bigint, ltrim(rtrim(bargz.codbarra))) =
            try_convert(bigint, ltrim(rtrim(src.barras)))

 where bargz.termvenda <> src.preco
       and src.cdprod = '7040042'

-- ETAPA 1 — montar staging local

if object_id('tempdb..#AtualizaBarraRel') is not null
    drop table #AtualizaBarraRel

select distinct
       bargz.cdprod,
       bargz.codbarra,
       cast(bar.preco as decimal(18,3)) as novo_preco,
       bargz.termvenda
into #AtualizaBarraRel
  from TBS010 pro with (nolock)

 inner join dbo.vw_TabelaCodigosBarrasGZ bar
         on bar.codigo = pro.PROCOD

 inner join dbo.vw_PrecoLojaGeral pre
         on pre.codigo = pro.PROCOD

 inner join openquery(
       MYSQLGZBBPDV3,
       '
       select cdprod,
              codbarra,
              termvenda
         from barrarel
       '
 ) bargz

         on try_convert(bigint, ltrim(rtrim(bargz.cdprod))) =
            try_convert(bigint, ltrim(rtrim(pro.PROCOD)))

        and try_convert(bigint, ltrim(rtrim(bargz.codbarra))) =
            try_convert(bigint, ltrim(rtrim(bar.barras)))

 where pre.custo > 0
   and isnull(bargz.termvenda,0) <> isnull(bar.preco,0)

select *
  from #AtualizaBarraRel
 order by cdprod, codbarra

