-- insert para rodar no mysql

if object_id('tempdb..#InsertBarraRel') is not null
    drop table #InsertBarraRel

select distinct
       right(replicate(' ',20) + rtrim(cast(try_convert(bigint, pro.PROCOD) as char(20))),20) as cdprod,
       --right(replicate(' ',20) + rtrim(cast(try_convert(bigint, bar.barras) as char(20))),20) as codbarra,
       right(replicate(' ',20) + rtrim(bar.barras),20) as codbarra,
       round(bar.embalagem,3)                               as multiplos,
       round(bar.preco,3)                                   as termvenda
into #InsertBarraRel

  from dbo.vw_TabelaCodigosBarrasGZ as bar

 inner join TBS010 pro with (nolock)
         on pro.PROCOD = bar.codigo

 where not exists (
        select 0
          from openquery(
               MYSQLGZBBPDV3,
               'select cdprod, codbarra from barrarel'
          ) bargz

         where try_convert(bigint, ltrim(rtrim(bargz.cdprod))) =
               try_convert(bigint, ltrim(rtrim(bar.codigo)))

           --and try_convert(bigint, ltrim(rtrim(bargz.codbarra))) =
               --try_convert(bigint, ltrim(rtrim(bar.barras)))
           
           and ltrim(rtrim(bargz.codbarra)) = ltrim(rtrim(bar.barras)) collate database_default
 )

select *
  from #InsertBarraRel
 order by cdprod, codbarra

select 'insert into barrarel (cdprod, codbarra, multiplos, termvenda) values (''' + cdprod + ''', ''' + codbarra + ''', ' + replace(cast(multiplos as varchar(30)), ',', '.') + ', ' + replace(cast(termvenda as varchar(30)), ',', '.') + ');' as comando
  from #InsertBarraRel
 order by cdprod, codbarra

