       count(*)                 as qtd
  from openquery(MYSQLGZBBPDV3, 'select cdprod, codbarra from barrarel') b  
 group by cast(b.codbarra as unsigned)
having count(*) > 1;

select codigo_normalizado,
       count(*) as qtd
  from (
        select case 
                 when b.codbarra like '%[^0]%'
                 then substring(b.codbarra, patindex('%[^0]%', b.codbarra), len(b.codbarra))
                 else '0'
               end as codigo_normalizado
          from openquery(MYSQLGZBBPDV3, 'select cdprod, codbarra from barrarel') b
       ) x
 group by codigo_normalizado
having count(*) > 1;

