-- ajustes códigos de barras

drop table #produtos

select p.PROCOD
       ,p.PROUM1
       ,p.PROUM1QTD
       ,p.PROUM2
       ,p.PROUM2QTD
       ,p.PROUM3
       ,p.PROUM3QTD
       ,p.PROUM4
       ,p.PROUM4QTD
  into #produtos
  from TBS010 p with (nolock)

-- códigos de barras associados a quantidade da embalagem que não existem

select *
  from TBS0103 b with (nolock)
 where b.CBPQTDEMB > 1
       and not exists ( select 'ne'
                          from #produtos p
                         where p.PROCOD = b.CBPPROCOD
                               and ( p.PROUM2QTD = b.CBPQTDEMB
                                     or p.PROUM3QTD = b.CBPQTDEMB
                                     or p.PROUM4QTD = b.CBPQTDEMB
                               )
       )

-- elimina os registros do select acima

begin tran
DELETE b
FROM TBS0103 b
WHERE b.CBPQTDEMB > 1
  AND NOT EXISTS (
        SELECT 1
        FROM #produtos p
        WHERE p.PROCOD = b.CBPPROCOD
          AND (
                 p.PROUM2QTD = b.CBPQTDEMB
              OR p.PROUM3QTD = b.CBPQTDEMB
              OR p.PROUM4QTD = b.CBPQTDEMB
          )
      );

rollback tran
commit tran

select t.CBPPROCOD
       ,count(*)
  from (
select *
  from TBS0103 b with (nolock)
 where b.CBPQTDEMB > 1
       and not exists ( select 'ne'
                          from #produtos p
                         where p.PROCOD = b.CBPPROCOD
                               and ( p.PROUM2QTD = b.CBPQTDEMB
                                     or p.PROUM3QTD = b.CBPQTDEMB
                                     or p.PROUM4QTD = b.CBPQTDEMB
                               )
       )

  ) t
group by t.CBPPROCOD

-- códigos de barras duplicados

select *
  from TBS0103 b with (nolock)
 where Len(b.CBPCODBAR) = 12

select t.codigo
       ,t.barras
       ,t.regs
       ,Len(t.barras) as digs
  from (
select b.CBPPROCOD as codigo
       --,b.CBPCODBAR
       ,CAST(b.CBPCODBAR AS BIGINT) as barras
       ,count(*) as regs
  from TBS0103 b with (nolock)
 group by b.CBPPROCOD
          ,CAST(b.CBPCODBAR AS BIGINT)
having count(*) > 1
  ) t

-- código de barras com erro de cadastro (inválidos)
SELECT CBPPROCOD,
       CBPCODBAR
FROM TBS0103
WHERE TRY_CONVERT(BIGINT, CBPCODBAR) IS NULL
      AND CBPCODBAR IS NOT NULL;

SELECT t.codigo,
       t.barras,
       t.regs,
       LEN(CAST(t.barras AS VARCHAR(20))) AS digs
       ,(select PRODES from TBS010 p with (nolock) where p.PROCOD = t.codigo)
FROM (
    SELECT b.CBPPROCOD AS codigo,
           TRY_CONVERT(BIGINT, b.CBPCODBAR) AS barras,
           COUNT(*) AS regs
    FROM TBS0103 b WITH (NOLOCK)
    WHERE TRY_CONVERT(BIGINT, b.CBPCODBAR) IS NOT NULL
    GROUP BY b.CBPPROCOD,
             TRY_CONVERT(BIGINT, b.CBPCODBAR)
    HAVING COUNT(*) > 1
) t;


select b.CBPPROCOD
       ,b.CBPCODBAR
       ,(select PRODES from TBS010 p with (nolock) where p.PROCOD = b.CBPPROCOD)
  from TBS0103 b with (nolock)
 where Left(b.CBPCODBAR,2) = '00'
       and subString(b.CBPCODBAR,3,1) <> '0'
       and Len(b.CBPCODBAR) = 12

-- stored procedure

CREATE PROCEDURE dbo.usp_ExportarProdutosGZ
(
      @Metodo     VARCHAR(10),
      @DiaAtual   BIT = 0,
      @Dias       INT = NULL,
      @Todos      BIT = 0
)
AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @DataDe DATE;
    DECLARE @DataAte DATE;

    IF @Todos = 0
    BEGIN

        SET @DataDe =
            DATEADD(DAY,
                    -ISNULL(@Dias,0),
                    CAST(GETDATE() AS DATE));

        SET @DataAte =
            CASE
                WHEN @DiaAtual = 1
                THEN CAST(GETDATE() AS DATE)
                ELSE DATEADD(DAY,-1,CAST(GETDATE() AS DATE))
            END;

    END

    SELECT
         0 as aliqFcp
        ,0 as aliqFcpRet
        ,0 as aliqFcpSt
        ,0.9 as aliquotaCbs
        ,0 as aliquotaCofinsCompra
        ,pc.aliqcofins as aliquotaCofinsVenda
        ,0 as aliquotaIbsMunic
        ,0.1 as aliquotaIbsUf
        ,0 as aliquotaIcmsCompra
        ,0 as aliquotaIpiVenda
        ,0 as aliquotaIs
        ,0 as aliquotaPisCompra
        ,pc.aliqpis as aliquotaPisVenda
        ,iif(len(ltrim(pro.PROCEST))=7,pro.PROCEST,'') as cest
        ,trib.cClassTrib as classificacaoTributariaIbsCbs
        ,ltrim(rtrim(pro.PROCOD)) as codigo
        ,iif(pro.PROSTBB in ('20','30','40','41','50','51','70','90'),
             'SEM CBENEF','') as codigoBeneficiario
        ,'S' as contSaldo
        ,pc.cstcofins as cstCofinsVenda
        ,trib.CST as cstIbsUf
        ,pc.cstpis as cstPisVenda
        ,LEFT(LTRIM(
            ISNULL(NULLIF(pro.PRODESPDV,''),pro.PRODES)
         ),40) as descricao
        ,LEFT(LTRIM(
            ISNULL(NULLIF(pro.PRODESPDVRED,''),pro.PRODES)
         ),24) as descricaoResumida
        ,LTRIM(RTRIM(pro.PROCOD)) as ean
        ,iif(len(ltrim(pro.PROCLAFIS))=8,
             RTRIM(pro.PROCLAFIS),'') as ncm
        ,pro.PROSTBA as origem
        ,trib.redCBS as percentualReducaoDeBaseCbs
        ,trib.redIBS as percentualReducaoDeBaseIbsMunicipal
        ,trib.redIBS as percentualReducaoDeBaseIbsUf
        ,ISNULL(ROUND(pre.custo,3),0) as precoCusto
        ,ISNULL(ROUND(pre.preco1,3),0) as precoTerminal
        ,ISNULL(ROUND(pre.preco1,3),0) as precoVenda
        ,'ATIVO' as situacao
        ,pro.TGZCOD as tributacao
        ,pro.PROUM1 as unidade
    FROM TBS010 pro WITH(NOLOCK)

    LEFT JOIN dbo.vw_PrecoLojaGeral pre
        ON pre.codigo = pro.PROCOD

    OUTER APPLY dbo.fn_RetornaTributacaoProduto(0,pro.PROCOD) trib

    OUTER APPLY PisCofins(pro.PROEMPCOD,pro.PROCOD) pc

    WHERE pre.preco1 > 0

      AND (
            @Todos = 1

            OR

            (
                @Metodo = 'POST'
                AND
                (
                    pro.PRODATCAD BETWEEN @DataDe AND @DataAte
                    OR CAST(pro.PRODATIMP AS DATE)
                       BETWEEN @DataDe AND @DataAte
                )
            )

            OR

            (
                @Metodo = 'PATCH'
                AND
                (
                    CAST(pro.PRODATALT AS DATE)
                        BETWEEN @DataDe AND @DataAte

                    OR CAST(pro.PRODATIMP AS DATE)
                        BETWEEN @DataDe AND @DataAte

                    OR pre.atualizado
                        BETWEEN @DataDe AND @DataAte
                )
            )
      )

    ORDER BY pro.PROCOD;

END
GO

-- uso

exec dbo.usp_ExportarProdutosGZ
     @Metodo = 'POST',
     @Dias = 4,
     @DiaAtual = 1;

