odo) = 'PATCH' AND (((@DataDe IS NULL OR CAST(pro.PRODATALT AS DATE) >= @DataDe) AND (@DataAte IS NULL OR CAST(pro.PRODATALT AS DATE) <= @DataAte)) OR ((@DataDe IS NULL OR CAST(pro.PRODATIMP AS DATE) >= @DataDe) AND (@DataAte IS NULL OR CAST(pro.PRODATIMP AS DATE) <= @DataAte)) OR ((@DataDe IS NULL OR pre.atualizado >= @DataDe) AND (@DataAte IS NULL OR pre.atualizado <= @DataAte))))) ORDER BY pro.PROCOD;
go

