declare @Metodo varchar(10),@DataDe date  = null,@DataAte date = null set nocount on set @Metodo = 'PATCH'	IF UPPER(@Metodo) NOT IN ('POST','PATCH') BEGIN RAISERROR('Método inválido. Utilize POST ou PATCH.',16,1) RETURN END CREATE TABLE #Produtos (PROCOD VARCHAR(20),PRODES VARCHAR(40)); INSERT INTO #Produtos (PROCOD,PRODES) SELECT DISTINCT pro.PROCOD,LEFT(CASE WHEN ISNULL(pro.PRODESPDV,'') = '' THEN LTRIM(pro.PRODES) ELSE LTRIM(pro.PRODESPDV) END,40) FROM TBS0103 bar WITH (NOLOCK) INNER JOIN TBS010 pro WITH (NOLOCK) ON pro.PROCOD = bar.CBPPROCOD INNER JOIN dbo.vw_PrecoLojaGeral pre ON pre.codigo = bar.CBPPROCOD WHERE pro.TGZCOD > 0 AND pre.custo > 0 AND (@DataDe IS NULL OR (UPPER(@Metodo) = 'POST' AND ((pro.PRODATCAD >= @DataDe AND (@DataAte IS NULL OR pro.PRODATCAD <= @DataAte)) OR (CAST(pro.PRODATIMP AS DATE) >= @DataDe AND (@DataAte IS NULL OR CAST(pro.PRODATIMP AS DATE) <= @DataAte)) OR (bar.CBPDATCAD >= @DataDe AND (@DataAte IS NULL OR bar.CBPDATCAD <= @DataAte)))) OR (UPPER(@Metodo) = 'PATCH' AND ((CAST(pro.PRODATALT AS DATE) >= @DataDe AND (@DataAte IS NULL OR CAST(pro.PRODATALT AS DATE) <= @DataAte)) OR(CAST(pro.PRODATIMP AS DATE) >= @DataDe AND (@DataAte IS NULL OR CAST(pro.PRODATIMP AS DATE) <= @DataAte)) OR(pre.atualizado >= @DataDe AND (@DataAte IS NULL OR pre.atualizado <= @DataAte)) OR (bar.CBPDATALT >= @DataDe AND (@DataAte IS NULL OR bar.CBPDATALT <= @DataAte))))); SELECT LTRIM(RTRIM(bar.barras)) AS codigoBarras,LTRIM(STR(CAST(pro.PROCOD AS BIGINT))) AS codigoProduto,pro.PRODES AS descricao,0 AS lojas,ROUND(bar.preco,3) AS preco,ROUND(bar.embalagem,3) AS quantidade FROM dbo.vw_TabelaCodigosBarrasGZ bar INNER JOIN #Produtos pro ON pro.PROCOD = bar.codigo COLLATE DATABASE_DEFAULT ORDER BY bar.codigo;
go

