o,3), 0) as precoCusto,0 as precoEspecial,0 as precoMaximo,0 as precoMinimo,0 as precoPromocao,isnull(round(pre.preco1,3), 0) as precoTerminal,isnull(round(pre.preco1,3), 0) as precoVenda,0 as quantidadeEstoque,'' as referencia,0 as setor,'ATIVO' as situacao,iif(pro.PROUM1 in('KG','MT'),'N','S') as soInteiro,'N' as solicitaSenha,0 as tipoCalcBcFcp,0 as tipoCalcBcFcpSt,pro.TGZCOD as tributacao,pro.PROUM1 as unidade,0 as valorUnitCofinsCompra,0 as valorUnitCofinsVenda,0 as valorUnitPisCompra,0 as valorUnitPisVenda,iif(pro.PROUM1 in('KG','MT'),'S','N') as variavel FROM TBS010 pro WITH (NOLOCK) LEFT JOIN dbo.vw_PrecoLojaGeral pre ON pre.codigo = pro.PROCOD OUTER APPLY dbo.fn_RetornaTributacaoProduto(0, pro.PROCOD) trib OUTER APPLY PisCofins(pro.PROEMPCOD, pro.PROCOD) pc WHERE pre.preco1 > 0 AND ((UPPER(@Metodo) = 'POST' AND (((@DataDe IS NULL OR pro.PRODATCAD >= @DataDe) AND (@DataAte IS NULL OR pro.PRODATCAD <= @DataAte)) OR ((@DataDe IS NULL OR CAST(pro.PRODATIMP AS DATE) >= @DataDe) AND (@DataAte IS NULL OR CAST(pro.PRODATIMP AS DATE) <= @DataAte)))) OR (UPPER(@Metodo) = 'PATCH' AND (((@DataDe IS NULL OR CAST(pro.PRODATALT AS DATE) >= @DataDe) AND (@DataAte IS NULL OR CAST(pro.PRODATALT AS DATE) <= @DataAte)) OR ((@DataDe IS NULL OR CAST(pro.PRODATIMP AS DATE) >= @DataDe) AND (@DataAte IS NULL OR CAST(pro.PRODATIMP AS DATE) <= @DataAte)) OR ((@DataDe IS NULL OR pre.atualizado >= @DataDe) AND (@DataAte IS NULL OR pre.atualizado <= @DataAte))))) ORDER BY pro.PROCOD;
